# fills resolution
def resolve(dotted):
    parts = dotted.split(".")
    obj=None
    for i in range(len(parts),0,-1):
        try:
            obj = importlib.import_module(".".join(parts[:i])); rest=parts[i:]; break
        except ImportError:
            continue
    else:
        obj = __builtins__.__dict__.get(parts[0], None) if not isinstance(__builtins__, dict) else __builtins__.get(parts[0])
        if obj is None: return False
        rest = parts[1:]
    for r in rest:
        if not hasattr(obj, r): return False
        obj = getattr(obj, r)
    return True
miss=[]
for u in stdlib.load_units('training/stdlib/units'):
    for f in u.fills:
        if not resolve(f): miss.append((u.name,f))
print("fills-unresolved:", miss)

