def chain(*iterables):
    out = []
    for it in iterables:
        for x in it:
            out.append(x)
    return out


def groupby_sorted(rows, keyfunc):
    groups = []
    last = None
    cur = None
    for r in rows:
        k = keyfunc(r)
        if cur is None or k != last:
            cur = []
            groups.append((k, cur))
            last = k
        cur.append(r)
    return groups


def accumulate(seq):
    out = []
    total = None
    for x in seq:
        total = x if total is None else total + x
        out.append(total)
    return out

