import datetime, calendar

def is_leap(y):
    return calendar.isleap(y)

def days_in_month(y, m):
    return calendar.monthrange(y, m)[1]

def isoformat(y, m, d):
    return datetime.date(y, m, d).isoformat()

def datetime_isoformat(y, m, d, hh=0, mm=0, ss=0, sep="T"):
    return datetime.datetime(y, m, d, hh, mm, ss).isoformat(sep)

def fromisoformat(s):
    d = datetime.date.fromisoformat(s)
    return (d.year, d.month, d.day)

def strftime(fmt, y, m, d, hh=0, mm=0, ss=0):
    return datetime.datetime(y, m, d, hh, mm, ss).strftime(fmt)

