def dedent(text):
    lines = text.split("\n")
    blanked = []
    for line in lines:
        only_ws = len(line) > 0
        for ch in line:
            if ch != " " and ch != "\t":
                only_ws = False
                break
        if only_ws:
            blanked.append("")
        else:
            blanked.append(line)

    margin = None
    for line in blanked:
        i = 0
        while i < len(line) and (line[i] == " " or line[i] == "\t"):
            i = i + 1
        if i >= len(line):
            continue
        indent = line[:i]
        if margin is None:
            margin = indent
        elif indent.startswith(margin):
            pass
        elif margin.startswith(indent):
            margin = indent
        else:
            j = 0
            while j < len(margin) and j < len(indent) and margin[j] == indent[j]:
                j = j + 1
            margin = margin[:j]

    if margin:
        out = []
        for line in blanked:
            if line.startswith(margin):
                out.append(line[len(margin):])
            else:
                out.append(line)
        return "\n".join(out)
    return "\n".join(blanked)


def indent(text, prefix, predicate=None):
    out = []
    for line in text.splitlines(True):
        if predicate is None:
            keep = line.strip()
        else:
            keep = predicate(line)
        if keep:
            out.append(prefix + line)
        else:
            out.append(line)
    return "".join(out)

import hashlib, hmac
src = open('/home/user/lypning/training/stdlib/units/hashlib_digest.py').read()
helpers, cases = src.split('# --- cases ---')
ns = {}
exec(compile(helpers, 'h', 'exec'), ns)
real = dict(ns)
FOUR = ('md5', 'sha1', 'sha256', 'sha512')

def _guard(name):
    # The unit documents that only these four names dispatch, and that an
    # unknown one is ValueError with hashlib.new's own message.
    if name not in FOUR:
        raise ValueError("unsupported hash type " + name)

def _digest(name, data):
    _guard(name)
    return hashlib.new(name, data).digest()

def _hexdigest(name, data):
    _guard(name)
    return hashlib.new(name, data).hexdigest()

def _digest_size(name):
    _guard(name)
    return hashlib.new(name).digest_size

def _block_size(name):
    _guard(name)
    return hashlib.new(name).block_size

def _digest_stream(name, chunks):
    _guard(name)
    h = hashlib.new(name)
    for c in chunks:
        h.update(c)
    return h.digest()

def _hmac_digest(name, key, message):
    _guard(name)
    return hmac.new(key, message, name).digest()

def _hmac_hexdigest(name, key, message):
    _guard(name)
    return hmac.new(key, message, name).hexdigest()

def _pbkdf2(name, password, salt, iterations, dklen=None):
    _guard(name)
    if iterations < 1:
        raise ValueError("iteration value must be greater than 0.")
    if dklen is not None and dklen < 1:
        raise ValueError("key length must be greater than 0.")
    return hashlib.pbkdf2_hmac(name, password, salt, iterations, dklen)

real.update({'digest': _digest, 'hexdigest': _hexdigest, 'digest_size': _digest_size,
             'block_size': _block_size, 'digest_stream': _digest_stream,
             'hmac_digest': _hmac_digest, 'hmac_hexdigest': _hmac_hexdigest,
             'pbkdf2_hmac': _pbkdf2})
exec(compile(cases, 'c', 'exec'), real)

