import ast, sys, importlib, pathlib
SEP = "# --- cases ---"
ok = True
for p in sorted(pathlib.Path('/home/user/lypning/training/stdlib/units').glob('*.py')):
    if p.stem not in ('fnmatch_match','collections_counter','bigint_arith','hashlib_digest','base64_codec'):
        continue
    text = p.read_text()
    problems = []
    if text.count(SEP) != 1:
        problems.append('separator count %d' % text.count(SEP))
    if not text.endswith('\n') or text.endswith('\n\n'):
        problems.append('trailing newline')
    tree = ast.parse(text)
    doc = ast.get_docstring(tree)
    if not doc or not doc.strip():
        problems.append('no module docstring')
    lines = text.split('\n')
    fills = [l for l in lines if l.startswith('# fills:')]
    ref = [l for l in lines if l.startswith('# reference:')]
    if len(fills) != 1: problems.append('fills lines %d' % len(fills))
    if len(ref) != 1: problems.append('reference lines %d' % len(ref))
    names = [n.strip() for n in fills[0][len('# fills:'):].split(',')]
    if not names or any(not n for n in names): problems.append('empty fill name')
    rm = ref[0][len('# reference:'):].strip()
    if rm != '-':
        try: importlib.import_module(rm)
        except Exception as e: problems.append('reference not importable: %s' % e)
    helpers, cases = text.split(SEP)
    ht = ast.parse(helpers)
    for node in ht.body:
        if isinstance(node, (ast.FunctionDef, ast.Import, ast.ImportFrom, ast.Assign)):
            continue
        if isinstance(node, ast.Expr) and isinstance(node.value, ast.Constant):
            continue
        problems.append('top-level side effect above separator: %s line %d' % (type(node).__name__, node.lineno))
    ct = ast.parse(cases)
    for node in ct.body:
        if isinstance(node, ast.Expr) and isinstance(node.value, ast.Call) and getattr(node.value.func, 'id', '') == 'print':
            continue
        if isinstance(node, ast.Assign):
            continue
        problems.append('non-print statement below separator: %s line %d' % (type(node).__name__, node.lineno))
    # banned constructs
    for node in ast.walk(tree):
        if isinstance(node, (ast.ClassDef, ast.AsyncFunctionDef, ast.Await, ast.Yield, ast.YieldFrom,
                             ast.NamedExpr, ast.Nonlocal)):
            problems.append('banned node %s line %d' % (type(node).__name__, node.lineno))
        if isinstance(node, (ast.FunctionDef,)) and node.decorator_list:
            problems.append('decorator line %d' % node.lineno)
        if isinstance(node, ast.arguments) and node.kwonlyargs:
            problems.append('kwonly args')
        if isinstance(node, ast.Set):
            problems.append('set display line %d' % node.lineno)
    print(('OK   ' if not problems else 'FAIL ') + p.name + ('' if not problems else '  ' + '; '.join(problems)))
    if problems: ok = False
sys.exit(0 if ok else 1)

