def _exact_total(values):
    n = 0
    d = 1
    special = 0.0
    has_special = False
    all_int = True
    for x in values:
        if isinstance(x, float):
            all_int = False
            if not math.isfinite(x):
                has_special = True
                special = special + x
                continue
        xn, xd = x.as_integer_ratio()
        n, d = _ratio_add(n, d, xn, xd)
    return (n, d, all_int, has_special, special)

def mean(data):
    values = list(data)
    count = len(values)
    if count < 1:
        raise ValueError("mean requires at least one data point")
    n, d, all_int, has_special, special = _exact_total(values)
    if has_special:
        return special / count
    n, d = _reduce(n, d * count)
    if all_int and d == 1:
        return n
    return _frac_to_float(n, d)

def fsum(data):
    values = []
    for x in data:
        values.append(float(x))
    n = 0
    d = 1
    special = 0.0
    has_special = False
    for x in values:
        if not math.isfinite(x):
            has_special = True
            special = special + x
            continue
        xn, xd = x.as_integer_ratio()
        n, d = _ratio_add(n, d, xn, xd)
    if has_special:
        return special
    return _frac_to_float(n, d)

def fmean(data, weights=None):
    values = list(data)
    count = len(values)
    if weights is None:
        if count < 1:
            raise ValueError("fmean requires at least one data point")
        return fsum(values) / count
    w = list(weights)
    if count != len(w):
        raise ValueError("data and weights must be the same length")
    products = []
    i = 0
    while i < count:
        products.append(float(values[i]) * float(w[i]))
        i = i + 1
    num = fsum(products)
    den = fsum(w)
    if not den:
        raise ValueError("sum of weights must be non-zero")
    return num / den

