def settle(v, depth=0):
    if depth > 3:
        return v
    if isinstance(v, tuple):
        return tuple(settle(x, depth + 1) for x in v)
    if isinstance(v, (str, bytes, bytearray, list, dict, set, frozenset)):
        return v
    if hasattr(v, "__next__") and hasattr(v, "__iter__"):
        return [settle(x, depth + 1) for x in v]
    return v

def wrap(fn):
    @functools.wraps(fn)
    def inner(*a, **k):
        return settle(fn(*a, **k))
    return inner

