import math

def _reduce(n, d):
    if d < 0:
        n = -n
        d = -d
    g = math.gcd(abs(n), d)
    if g > 1:
        n = n // g
        d = d // g
    return (n, d)

def _ratio_add(an, ad, bn, bd):
    return _reduce(an * bd + bn * ad, ad * bd)

def _frac_to_float(n, d):
    if n == 0:
        return 0.0
    negative = n < 0
    if negative:
        n = -n
    shift = n.bit_length() - d.bit_length() - 53
    if shift >= 0:
        num = n
        den = d << shift
    else:
        num = n << -shift
        den = d
    q = num // den
    if q.bit_length() > 53:
        shift = shift + 1
        den = den << 1
        q = num // den
    rem = num - q * den
    twice = rem * 2
    if twice > den or (twice == den and q % 2 == 1):
        q = q + 1
        if q.bit_length() > 53:
            q = q // 2
            shift = shift + 1
    value = q * (2.0 ** shift)
    if negative:
        return -value
    return value

