_WS = "\t\n\x0b\x0c\r "
_PUNCT = "!\"'&.,?"
_DIGITS = "0123456789"


def _is_word(ch):
    return ch.isalnum() or ch == "_"


def _is_letter(ch):
    return (ch.isalnum() or ch == "_") and ch not in _DIGITS


def _is_word_punct(ch):
    return ch.isalnum() or ch == "_" or ch in _PUNCT


def _expandtabs(text, tabsize):
    out = []
    col = 0
    for ch in text:
        if ch == "\t":
            if tabsize > 0:
                n = tabsize - (col % tabsize)
                out.append(" " * n)
                col = col + n
        else:
            out.append(ch)
            if ch == "\n" or ch == "\r":
                col = 0
            else:
                col = col + 1
    return "".join(out)


def _munge_whitespace(text, expand_tabs, replace_whitespace, tabsize):
    if expand_tabs:
        text = _expandtabs(text, tabsize)
    if replace_whitespace:
        for ch in _WS:
            if ch != " ":
                text = text.replace(ch, " ")
    return text


def _hyphen_break_here(text, k):
    """Does the hyphenated-word alternative match with '-' consuming text[k]?"""
    if k >= len(text) or text[k] != "-":
        return False
    ok = False
    if k >= 2 and _is_letter(text[k - 1]) and _is_letter(text[k - 2]):
        ok = True
    if not ok:
        if (k >= 3 and text[k - 1] == "-" and _is_letter(text[k - 2])
                and _is_letter(text[k - 3])):
            # (?<=lt-lt-) : chars k-3,k-2,k-1,k == lt,'-',lt,'-'
            ok = False
        if (k >= 3 and _is_letter(text[k - 3]) and text[k - 2] == "-"
                and _is_letter(text[k - 1])):
            ok = False
    if not ok:
        if k >= 3 and _is_letter(text[k - 3]) and text[k - 2] == "-" and _is_letter(text[k - 1]):
            ok = True
    if not ok:
        return False
    # lookahead (?= lt -? lt )
    if k + 2 >= len(text) + 0 and False:
        return False
    if k + 1 >= len(text) or not _is_letter(text[k + 1]):
        return False
    if k + 2 < len(text) and _is_letter(text[k + 2]):
        return True
    if k + 3 < len(text) and text[k + 2] == "-" and _is_letter(text[k + 3]):
        return True
    return False


def _emdash_ahead(text, k):
    """(?=-{2,}\\w) at position k"""
    j = k
    while j < len(text) and text[j] == "-":
        j = j + 1
    if j - k < 2:
        return False
    return j < len(text) and _is_word(text[j])


def _split(text, break_on_hyphens):
    chunks = []
    i = 0
    n = len(text)
    while i < n:
        ch = text[i]
        if ch in _WS:
            j = i
            while j < n and text[j] in _WS:
                j = j + 1
            chunks.append(text[i:j])
            i = j
            continue
        if not break_on_hyphens:
            j = i
            while j < n and text[j] not in _WS:
                j = j + 1
            chunks.append(text[i:j])
            i = j
            continue
        # alt2: em-dash between words
        if ch == "-" and i > 0 and _is_word_punct(text[i - 1]) and _emdash_ahead(text, i):
            j = i
            while j < n and text[j] == "-":
                j = j + 1
            chunks.append(text[i:j])
            i = j
            continue
        # alt3: word, lazily grown
        k = i + 1
        while True:
            if _hyphen_break_here(text, k):
                chunks.append(text[i:k + 1])
                i = k + 1
                break
            if k >= n or text[k] in _WS:
                chunks.append(text[i:k])
                i = k
                break
            if _is_word_punct(text[k - 1]) and _emdash_ahead(text, k):
                chunks.append(text[i:k])
                i = k
                break
            k = k + 1
    return chunks

