"""Differential for datetime_arith.py against the real datetime module."""
import datetime, calendar

def is_leap(y):
    return calendar.isleap(y)

def days_in_month(y, m):
    if m < 1 or m > 12:
        raise ValueError("month must be in 1..12")
    return calendar.monthrange(y, m)[1]

def _t(d):
    return (d.year, d.month, d.day)

def add_days(y, m, d, n):
    base = datetime.date(y, m, d)
    return _t(base + datetime.timedelta(days=n))

def sub_days(y, m, d, n):
    base = datetime.date(y, m, d)
    return _t(base - datetime.timedelta(days=n))

def add_weeks(y, m, d, n):
    return _t(datetime.date(y, m, d) + datetime.timedelta(weeks=n))

def days_between(y1, m1, d1, y2, m2, d2):
    return (datetime.date(y1, m1, d1) - datetime.date(y2, m2, d2)).days

def compare_dates(y1, m1, d1, y2, m2, d2):
    a = datetime.date(y1, m1, d1); b = datetime.date(y2, m2, d2)
    if a < b: return -1
    if a > b: return 1
    return 0

def next_day(y, m, d):
    return add_days(y, m, d, 1)

def prev_day(y, m, d):
    return sub_days(y, m, d, 1)

