import math

def _ratio_add(an, ad, bn, bd):
    n = an * bd + bn * ad
    d = ad * bd
    g = math.gcd(abs(n), d)
    if g > 1:
        n = n // g
        d = d // g
    return (n, d)

def _frac_to_float(n, d):
    """Correctly rounded float of the rational n/d (d > 0), round-half-even."""
    if n == 0:
        return 0.0
    negative = n < 0
    if negative:
        n = -n
    shift = n.bit_length() - d.bit_length() - 53
    if shift >= 0:
        num = n
        den = d << shift
    else:
        num = n << -shift
        den = d
    q = num // den
    rem = num - q * den
    if q.bit_length() > 53:
        shift = shift + 1
        den = den << 1
        q = num // den
        rem = num - q * den
    twice = rem * 2
    if twice > den or (twice == den and q % 2 == 1):
        q = q + 1
        if q.bit_length() > 53:
            q = q // 2
            shift = shift + 1
    value = q * (2.0 ** shift)
    if negative:
        return -value
    return value

def _exact_sum(values):
    n = 0
    d = 1
    special = 0.0
    has_special = False
    is_float = False
    for x in values:
        if isinstance(x, float):
            is_float = True
            if not math.isfinite(x):
                has_special = True
                special = special + x
                continue
        xn, xd = x.as_integer_ratio()
        n, d = _ratio_add(n, d, xn, xd)
    return (n, d, is_float, has_special, special)

def mean(data):
    values = list(data)
    count = len(values)
    if count < 1:
        raise ValueError("mean requires at least one data point")
    n, d, is_float, has_special, special = _exact_sum(values)
    if has_special:
        return special / count
    n, d = _ratio_add(n, d, 0, count)   # no-op add to reduce? placeholder
    return None

